<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { api } from './session'
import { formatDate } from './domain'
interface Comment { id: string; author_name: string; body: string; updated_at: string; created_at: string; can_edit: boolean; can_delete: boolean }
const props = defineProps<{ attemptId: string }>()
const items = ref<Comment[]>([]), total = ref(0), page = ref(1), body = ref(''), editing = ref<Comment | null>(null), busy = ref(false), error = ref('')
let generation = 0
async function load(next = 1) { const request = ++generation; error.value = ''; try { const data = await api<{ items: Comment[]; total: number }>('/results/' + props.attemptId + '/comments?page=' + next); if (request === generation) { items.value = data.items; total.value = data.total; page.value = next } } catch (err) { if (request === generation) error.value = (err as Error).message } }
async function save() { if (busy.value) return; busy.value = true; error.value = ''; try { await api('/results/' + props.attemptId + '/comments' + (editing.value ? '/' + editing.value.id : ''), { method: editing.value ? 'PATCH' : 'POST', body: JSON.stringify({ body: body.value, ...(editing.value ? { base_updated_at: editing.value.updated_at } : {}) }) }); body.value = ''; editing.value = null; await load(page.value) } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
function edit(comment: Comment) { editing.value = comment; body.value = comment.body }
async function remove(comment: Comment) { if (!window.confirm('Удалить комментарий?')) return; busy.value = true; error.value = ''; try { await api('/results/' + props.attemptId + '/comments/' + comment.id, { method: 'DELETE' }); if (editing.value?.id === comment.id) { editing.value = null; body.value = '' } await load(page.value) } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
watch(() => props.attemptId, () => { editing.value = null; body.value = ''; void load() }); onMounted(load)
</script>
<template>
  <section class="report-section" aria-label="Комментарии к результату"><h2>Комментарии команды</h2><p class="muted-text">Доступны сотрудникам с правом просмотра этого результата. Кандидат их не видит. Не добавляйте лишние персональные данные.</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><article v-for="comment in items" :key="comment.id" class="editor-card account-card"><strong>{{ comment.author_name }}</strong><p class="field-hint">{{ formatDate(comment.created_at) }}</p><p class="comment-body">{{ comment.body }}</p><div class="form-actions"><button v-if="comment.can_edit" class="text-button" :disabled="busy" @click="edit(comment)">Редактировать комментарий</button><button v-if="comment.can_delete" class="text-button danger" :disabled="busy" @click="remove(comment)">Удалить комментарий</button></div></article><div v-if="total > 20" class="image-pages"><button :disabled="busy || page <= 1" @click="load(page - 1)">Назад</button><span>{{ page }}</span><button :disabled="busy || page * 20 >= total" @click="load(page + 1)">Далее</button></div><form class="editor-card account-card" @submit.prevent="save"><label class="form-field">{{ editing ? 'Редактирование комментария' : 'Новый комментарий' }}<textarea v-model="body" maxlength="5000" rows="4" required :disabled="busy" /></label><button class="primary-button" :disabled="busy">{{ editing ? 'Сохранить комментарий' : 'Добавить комментарий' }}</button><button v-if="editing" class="text-button" type="button" @click="editing = null; body = ''">Отменить редактирование</button></form></section>
</template>
